{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required case field')
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('invalid case field type')
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError('required symbols must be strings')

    by_id = {}
    children = {}
    roots = []
    required_node_fields = ('id', 'parent', 'symbol', 'depth', 'removable', 'utility')
    for node in nodes:
        if not isinstance(node, dict) or any(field not in node for field in required_node_fields):
            raise ValueError('invalid node')
        node_id = node['id']
        parent = node['parent']
        symbol = node['symbol']
        depth = node['depth']
        utility = node['utility']
        if not isinstance(node_id, str) or not isinstance(symbol, str):
            raise ValueError('node id and symbol must be strings')
        if node_id in by_id:
            raise ValueError('duplicate node id')
        if parent is not None and not isinstance(parent, str):
            raise ValueError('invalid parent id')
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError('invalid depth')
        if not isinstance(node['removable'], bool):
            raise ValueError('invalid removable flag')
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError('invalid utility')
        by_id[node_id] = node
        children[node_id] = []
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError('tree must have one root')
    root_id = roots[0]
    if by_id[root_id]['depth'] != 0:
        raise ValueError('root must have depth zero')
    for node_id, node in by_id.items():
        parent = node['parent']
        if parent is not None:
            if parent not in by_id or parent == node_id:
                raise ValueError('unknown or self parent')
            if by_id[parent]['depth'] + 1 != node['depth']:
                raise ValueError('invalid tree depth')
            children[parent].append(node_id)

    seen = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError('cycle in tree')
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(by_id):
        raise ValueError('disconnected tree')

    active = set(by_id)
    counts = {}
    for node in nodes:
        symbol = node['symbol']
        counts[symbol] = counts.get(symbol, 0) + 1
    if any(counts.get(symbol, 0) == 0 for symbol in required_symbols):
        raise ValueError('required symbol is absent')

    candidates = sorted(nodes, key=lambda node: (-node['depth'], node['id']))
    removed = []
    for node in candidates:
        node_id = node['id']
        if not node['removable'] or node_id == root_id or node_id not in active:
            continue
        if any(child_id in active for child_id in children[node_id]):
            continue
        symbol = node['symbol']
        if symbol in required_symbols and counts[symbol] <= 1:
            continue
        active.remove(node_id)
        counts[symbol] -= 1
        removed.append(node_id)

    return {
        'removed_node_ids': removed,
        'retained_node_ids': sorted(active),
    }
"}
